frappe.ui.form.on('Car repair', {
    refresh: function(frm) {
        frm.remove_custom_button(__('Create Invoice'));

        // Show button if Car Repair is saved and Completed
        if (!frm.doc.__islocal && frm.doc.status === 'Completed') {
            frm.add_custom_button(__('Create Invoice'), () => create_sales_invoice(frm));
        }
    }
});

function create_sales_invoice(frm) {
    if (!frm.doc.customer_name) {
        frappe.msgprint(__('Please select a Customer before creating Sales Invoice.'));
        return;
    }

    if (!frm.doc.list_of_damage || frm.doc.list_of_damage.length === 0) {
        frappe.msgprint(__('No items in Car Repair. Cannot create Sales Invoice.'));
        return;
    }

    const company = frappe.defaults.get_user_default('Company') || "Your Company Name";
    const posting_date = frappe.datetime.nowdate();

    // Prepare Sales Invoice doc
    let si = frappe.model.get_new_doc('Sales Invoice');
    si.customer = frm.doc.customer_name;
    si.company = company;
    si.posting_date = posting_date;
    si.from_car_repair = 1;      // optional flag
    si.car_repair = frm.doc.name; // link to Car Repair
    si.items = [];

    // Add items from Car Repair
    frm.doc.list_of_damage.forEach(d => {
        if (d.part_required) {
            si.items.push({
                doctype: 'Sales Invoice Item',
                item_code: d.part_required,
                qty: d.qty || 1,
                rate: d.estimated_cost || 0,
                description: d.assigned_to ? `Assigned To: ${d.assigned_to}` : ''
            });
        }
    });

    // Insert Sales Invoice directly
    frappe.db.insert(si)
        .then(doc => {
            frappe.show_alert({
                message: __('Sales Invoice {0} created successfully!', [doc.name]),
                indicator: 'green'
            });

            // Optionally open the saved Sales Invoice
            frappe.set_route('Form', 'Sales Invoice', doc.name);
        })
        .catch(err => {
            frappe.msgprint(__('Error creating Sales Invoice: ') + err.message);
        });
}

