frappe.ui.form.on("Car Diagnosis", {
    customer_name: function(frm) {
        if (!frm.doc.customer_name) return;

        frappe.db.get_list("Car Repair Request", {
            filters: { "customer_name": frm.doc.customer_name },
            fields: ["car", "car_model", "license_plate", "email", "phone", "repair_request_date", "priority"],
            order_by: "creation desc",
            limit_page_length: 1
        }).then(requests => {
            if(requests && requests.length) {
                const req = requests[0];
                console.log("Car Repair Request Data:", req);

                frm.set_value("car", req.car);
                frm.set_value("model", req.car_model);
                frm.set_value("license_plate", req.license_plate);
                frm.set_value("email_id", req.email);
                frm.set_value("phone", req.phone);
                frm.set_value("date_of_receipt", req.repair_request_date);

                // Dynamic priority: add value to Select if it doesn't exist
                if(req.priority) {
                    let field = frm.get_field("priority");
                    if(!field.df.options.includes(req.priority)) {
                        // Add new option dynamically
                        field.df.options += `\n${req.priority}`;
                        field.refresh(); // Refresh field to apply new option
                    }
                    frm.set_value("priority", req.priority);
                }
            }
        });
    }
